import express, { ErrorRequestHandler, Express, Request, Response, Router } from "express";
import { ProjectService } from "../application/project-service";
import { TaskService } from "../application/task-service";
import { UserService } from "../application/user-service";
import { ConflictError, NotFoundError, ValidationError } from "../domain/errors";
import { TaskFilter } from "../domain/repositories";
import { isTaskStatus, TASK_STATUSES, TaskStatus } from "../domain/task";

export interface Services {
  users: UserService;
  projects: ProjectService;
  tasks: TaskService;
}

type Body = Record<string, unknown>;

function bodyOf(req: Request): Body {
  const body: unknown = req.body;
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    throw new ValidationError("Request body must be a JSON object");
  }
  return body as Body;
}

function requiredString(body: Body, field: string): string {
  const value = body[field];
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new ValidationError(`'${field}' is required and must be a non-empty string`);
  }
  return value;
}

function optionalString(body: Body, field: string): string | undefined {
  const value = body[field];
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`'${field}' must be a string`);
  }
  return value;
}

function parseStatus(value: unknown, field: string): TaskStatus {
  const normalized = typeof value === "string" ? value.trim().toLowerCase().replace(/[\s-]+/g, "_") : value;
  if (!isTaskStatus(normalized)) {
    throw new ValidationError(`'${field}' must be one of: ${TASK_STATUSES.join(", ")}`);
  }
  return normalized;
}

function parseDueDate(value: unknown): Date | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== "string") {
    throw new ValidationError("'dueDate' must be an ISO 8601 date string");
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new ValidationError("'dueDate' must be an ISO 8601 date string");
  }
  return date;
}

function singleQueryValue(req: Request, name: string): string | undefined {
  const value: unknown = req.query[name];
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`Query parameter '${name}' must be provided once`);
  }
  return value;
}

function param(req: Request, name: string): string {
  const value: unknown = req.params[name];
  if (typeof value !== "string") {
    throw new ValidationError(`Missing path parameter '${name}'`);
  }
  return value;
}

function usersRouter(services: Services): Router {
  const router = Router();

  router.post("/", (req: Request, res: Response) => {
    const body = bodyOf(req);
    const user = services.users.createUser({ name: requiredString(body, "name") });
    res.status(201).json(user);
  });

  router.get("/", (_req: Request, res: Response) => {
    res.json(services.users.listUsers());
  });

  router.get("/:userId", (req: Request, res: Response) => {
    res.json(services.users.getUser(param(req, "userId")));
  });

  return router;
}

function projectsRouter(services: Services): Router {
  const router = Router();

  router.post("/", (req: Request, res: Response) => {
    const body = bodyOf(req);
    const project = services.projects.createProject({ name: requiredString(body, "name") });
    res.status(201).json(project);
  });

  router.get("/", (_req: Request, res: Response) => {
    res.json(services.projects.listProjects());
  });

  router.get("/:projectId", (req: Request, res: Response) => {
    res.json(services.projects.getProject(param(req, "projectId")));
  });

  router.post("/:projectId/tasks", (req: Request, res: Response) => {
    const body = bodyOf(req);
    const task = services.tasks.addTask({
      projectId: param(req, "projectId"),
      title: requiredString(body, "title"),
      description: optionalString(body, "description") ?? "",
      dueDate: parseDueDate(body["dueDate"]),
      status: body["status"] === undefined ? undefined : parseStatus(body["status"], "status"),
      assigneeId: optionalString(body, "assigneeId") ?? null,
    });
    res.status(201).json(task);
  });

  router.get("/:projectId/tasks", (req: Request, res: Response) => {
    const filter: TaskFilter = {};
    const status = singleQueryValue(req, "status");
    if (status !== undefined) {
      filter.status = parseStatus(status, "status");
    }
    const assigneeId = singleQueryValue(req, "assigneeId");
    if (assigneeId !== undefined) {
      filter.assigneeId = assigneeId;
    }
    res.json(services.tasks.listTasks(param(req, "projectId"), filter));
  });

  router.get("/:projectId/tasks/:taskId", (req: Request, res: Response) => {
    res.json(services.tasks.getTask(param(req, "projectId"), param(req, "taskId")));
  });

  router.put("/:projectId/tasks/:taskId/assignee", (req: Request, res: Response) => {
    const body = bodyOf(req);
    const task = services.tasks.assignTask(
      param(req, "projectId"),
      param(req, "taskId"),
      requiredString(body, "userId"),
    );
    res.json(task);
  });

  router.post("/:projectId/tasks/:taskId/done", (req: Request, res: Response) => {
    res.json(services.tasks.markTaskDone(param(req, "projectId"), param(req, "taskId")));
  });

  return router;
}

const errorHandler: ErrorRequestHandler = (err: unknown, _req, res, _next) => {
  if (err instanceof ValidationError) {
    res.status(400).json({ error: err.message });
  } else if (err instanceof NotFoundError) {
    res.status(404).json({ error: err.message });
  } else if (err instanceof ConflictError) {
    res.status(409).json({ error: err.message });
  } else if (err instanceof SyntaxError) {
    res.status(400).json({ error: "Malformed JSON body" });
  } else {
    console.error(err);
    res.status(500).json({ error: "Internal server error" });
  }
};

export function createApp(services: Services): Express {
  const app = express();
  app.use(express.json());

  app.get("/health", (_req: Request, res: Response) => {
    res.json({ status: "ok" });
  });
  app.use("/users", usersRouter(services));
  app.use("/projects", projectsRouter(services));

  app.use((_req: Request, res: Response) => {
    res.status(404).json({ error: "Route not found" });
  });
  app.use(errorHandler);

  return app;
}

